            except Exception as exc:
                _logstream_fail(str(exc), as_json)
            if as_json:
                print(json.dumps(results, indent=2, ensure_ascii=False))
            else:
                for stats in results:
                    if stats.get("error"):
                        print(
                            f"  {stats.get('peer_name', stats['peer_url'])}: ERROR {stats['error']}"
