    match finally {
        TypedExpr::Echo {
            expression: None,
            location,
            ..
        } => {
            let var = latest_local_var.expect("echo with no previous step in a pipe");
            documents.push(self.echo(var.to_doc(), location)?);
        }
        _ => documents.push(self.expression(finally)?),
