pub struct Tracking(rc::Weak<()>);

impl Tracking {
    /// Returns `true` if the message of this [`Tracking`] has been processed
    /// by `update` logic.
    pub fn is_processed(&self) -> bool {
        self.0.strong_count() == 0
    }
}

