	e.splitID = h.tab.GetNode(h.splitID).HSplit(bottom)
	currentPaneIdx := h.tab.GetPane(h.splitID)
	if bottom {
		currentPaneIdx++
	}
	h.tab.AddPane(e, currentPaneIdx)
	h.tab.Resize()
	h.tab.SetActive(currentPaneIdx)
	return e
}

